package steps

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

//truebdd:concept given "installation"
func concept08bdc8ba20fbc17f8cbea598ca6da5bdbc121817e637f18277eb83c75896fcf3(state *State, args []string) error {
	const (
		hostRootFromSuite = "../.."
		commandPackage    = "./services/calc"
		commandName       = "double"
		programName       = "calc"
		buildDirPattern   = "calc-install-"
	)

	if state.CalcBinary != "" {
		return nil
	}

	hostRoot, err := filepath.Abs(hostRootFromSuite)
	if err != nil {
		return fmt.Errorf("resolve the host root %q: %w", hostRootFromSuite, err)
	}

	buildDir, err := os.MkdirTemp("", buildDirPattern)
	if err != nil {
		return fmt.Errorf("create a build directory under the host's tmp directory: %w", err)
	}

	program := filepath.Join(buildDir, programName)

	build := exec.Command("go", "build", "-o", program, commandPackage)
	build.Dir = hostRoot
	if output, err := build.CombinedOutput(); err != nil {
		return fmt.Errorf(
			"build the %q command from %s at the host root %s: %w: %s",
			commandName, commandPackage, hostRoot, err, strings.TrimSpace(string(output)),
		)
	}

	state.HostRoot = hostRoot
	state.CalcBinary = program

	return nil
}

package steps

import (
	"bytes"
	"fmt"
	"os/exec"
	"strings"
)

//truebdd:concept when "doubling"
func concept49c5ece16061081405dd19dacacf9182109378be8a0f1d472e9711fff19b790b(state *State, args []string) error {
	const commandName = "double"

	number := args[0]

	if state.CalcBinary == "" {
		return fmt.Errorf(
			"run the %q command with %s: the calculator program is not installed yet",
			commandName, number,
		)
	}

	state.DoubleStdout = ""

	var stdout, stderr bytes.Buffer

	run := exec.Command(state.CalcBinary, commandName, number)
	run.Dir = state.HostRoot
	run.Stdout = &stdout
	run.Stderr = &stderr

	if err := run.Run(); err != nil {
		return fmt.Errorf(
			"run %s %s %s from the host root %s: %w: %s",
			state.CalcBinary, commandName, number, state.HostRoot, err, strings.TrimSpace(stderr.String()),
		)
	}

	state.DoubleStdout = stdout.String()

	return nil
}

package steps

import (
	"fmt"
	"strconv"
	"strings"
)

//truebdd:concept then "result"
func concepted1de9371d2a7b37ce77d82464ab6737cf25f6c86f592518873001398dd1313e(state *State, args []string) error {
	const commandName = "double"

	expectedText := args[0]

	expected, err := strconv.Atoi(expectedText)
	if err != nil {
		return fmt.Errorf(
			"read the expected whole number %q written in the step: %w",
			expectedText, err,
		)
	}

	if state.DoubleStdout == "" {
		return fmt.Errorf(
			"observe the whole number the %q command printed, want %d: no stdout was kept from the %q command",
			commandName, expected, commandName,
		)
	}

	printed := strings.TrimSpace(state.DoubleStdout)

	actual, err := strconv.Atoi(printed)
	if err != nil {
		return fmt.Errorf(
			"read a whole number from the stdout %q the %q command printed: %w",
			state.DoubleStdout, commandName, err,
		)
	}

	if actual != expected {
		return fmt.Errorf(
			"the %q command printed %d on stdout, want the result %d",
			commandName, actual, expected,
		)
	}

	return nil
}

package steps

func Register(suite interface {
	Step(string, func(*State, []string) error)
}) {
	suite.Step("^the calculator is installed$", concept08bdc8ba20fbc17f8cbea598ca6da5bdbc121817e637f18277eb83c75896fcf3)

	suite.Step("^the Owner doubles (-?\\d+)$", concept49c5ece16061081405dd19dacacf9182109378be8a0f1d472e9711fff19b790b)

	suite.Step("^the result is (-?\\d+)$", concepted1de9371d2a7b37ce77d82464ab6737cf25f6c86f592518873001398dd1313e)
}

package steps

type State struct {
	// CalcBinary is the absolute path of the calculator program the Given
	// built under the host's tmp directory.
	CalcBinary string
	// HostRoot is the absolute host root the calculator program is run from.
	HostRoot string
	// DoubleStdout is the stdout the calculator's double command printed,
	// kept exactly as the process wrote it (the integer and a newline).
	DoubleStdout string
}
